package com.bank.flink.part;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Simulates a FORWARDING edge: each input lane is processed 1:1,
// records stay on their own lane, order preserved, NO shuffle.
class ForwardingStage {
    private static final Logger log = Logger.getLogger(ForwardingStage.class.getName());

    // Process one lane: filter out test txns, map RawTxn -> CleanTxn, in order.
    List<CleanTxn> processLane(int laneId, List<RawTxn> lane) {
        List<CleanTxn> out = new ArrayList<>();
        for (RawTxn raw : lane) {
            if (raw.isInternalTest()) {
                log.fine(() -> "Lane " + laneId + " filtered TEST txn");
                continue; // filter
            }
            out.add(new CleanTxn(raw.getAccountId(), raw.getAmount())); // map
        }
        log.info(() -> "FORWARD lane " + laneId + " produced " + out.size()
                + " clean txns (stayed on lane " + laneId + ", no shuffle)");
        return out;
    }
}
