package com.bank.flink.part;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Simulates a REDISTRIBUTING edge (keyBy): hash the accountId to pick the
// target subtask, so all txns for one account converge, then accumulate.
class RedistributingStage {
    private static final Logger log = Logger.getLogger(RedistributingStage.class.getName());

    private final int downstreamParallelism;
    private final Map<String, BigDecimal> totalsByAccount = new HashMap<>();
    private int crossLaneShuffles = 0;

    RedistributingStage(int downstreamParallelism) {
        this.downstreamParallelism = downstreamParallelism;
    }

    // keyBy routing: which downstream subtask handles this account?
    int targetSubtask(String accountId) {
        return Math.floorMod(accountId.hashCode(), downstreamParallelism);
    }

    // Shuffle one lane's clean txns to their keyed subtasks and accumulate.
    void redistribute(int sourceLane, List<CleanTxn> cleanTxns) {
        for (CleanTxn t : cleanTxns) {
            int target = targetSubtask(t.getAccountId());
            if (target != sourceLane) {
                crossLaneShuffles++; // this record crossed the network
            }
            totalsByAccount.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
            log.info(() -> "REDISTRIBUTE " + t.getAccountId() + " amount " + t.getAmount()
                    + " lane " + sourceLane + " -> subtask " + target);
        }
    }

    Map<String, BigDecimal> getTotalsByAccount() { return totalsByAccount; }
    int getCrossLaneShuffles() { return crossLaneShuffles; }
}
