package com.bank.flink.part;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: forwarding stage (1:1 per lane) then redistributing stage
// (keyBy hash shuffle) producing per-account totals.
public class PartitioningDemo {
    private static final Logger log = Logger.getLogger(PartitioningDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new PartLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ForwardingStage forwarding = new ForwardingStage();
        RedistributingStage redistributing = new RedistributingStage(3);

        // Three input lanes, each with a mix of accounts and one test txn.
        List<List<RawTxn>> lanes = List.of(
            List.of(new RawTxn("SAV2001", new BigDecimal("100"), false),
                    new RawTxn("CUR3001", new BigDecimal("200"), false),
                    new RawTxn("SAV2001", new BigDecimal("0"), true)),      // test -> filtered
            List.of(new RawTxn("SAV2001", new BigDecimal("300"), false),
                    new RawTxn("CUR3001", new BigDecimal("400"), false)),
            List.of(new RawTxn("CUR3001", new BigDecimal("500"), false),
                    new RawTxn("SAV2001", new BigDecimal("600"), false))
        );

        for (int lane = 0; lane < lanes.size(); lane++) {
            List<CleanTxn> clean = forwarding.processLane(lane, lanes.get(lane)); // FORWARD 1:1
            redistributing.redistribute(lane, clean);                             // REDISTRIBUTE keyBy
        }

        log.info(() -> "Per-account totals = " + redistributing.getTotalsByAccount());
        log.info(() -> "Cross-lane shuffles = " + redistributing.getCrossLaneShuffles());
    }
}

